177	    @Override
178	    public int hashCode() {
179	        final int prime = 31;
180	        int result = 1;
181	        result = prime * result + ((createdDate == null) ? 0 : createdDate.hashCode());
182	        result = prime * result + ((userLabel == null) ? 0 : userLabel.hashCode());
183	        result = prime * result + ((secretData == null) ? 0 : secretData.hashCode());
184	        result = prime * result + ((credentialData == null) ? 0 : credentialData.hashCode());
185	        result = prime * result + ((temporary == null) ? 0 : temporary.hashCode());
186	        result = prime * result + ((type == null) ? 0 : type.hashCode());
187	        result = prime * result + ((id == null) ? 0 : id.hashCode());
188	        result = prime * result + ((value == null) ? 0 : value.hashCode());
189	        result = prime * result + ((priority == null) ? 0 : priority);
190	        return result;
191	    }
