195	        if (this == obj)
196	            return true;
197	        if (obj == null)
198	            return false;
199	        if (getClass() != obj.getClass())
200	            return false;
201	        CredentialRepresentation other = (CredentialRepresentation) obj;
202	        if (secretData == null) {
203	            if (other.secretData != null)
204	                return false;
205	        } else if (!secretData.equals(other.secretData))
206	            return false;
207	        if (credentialData == null) {
208	            if (other.credentialData != null)
209	                return false;
210	        } else if (!credentialData.equals(other.credentialData))
211	            return false;
212	        if (createdDate == null) {
213	            if (other.createdDate != null)
214	                return false;
215	        } else if (!createdDate.equals(other.createdDate))
216	            return false;
217	        if (userLabel == null) {
218	            if (other.userLabel != null)
219	                return false;
220	        } else if (!userLabel.equals(other.userLabel))
221	            return false;
222	        if (temporary == null) {
223	            if (other.temporary != null)
224	                return false;
225	        } else if (!temporary.equals(other.temporary))
226	            return false;
227	        if (type == null) {
228	            if (other.type != null)
229	                return false;
230	        } else if (!type.equals(other.type))
231	            return false;
232	        if (id == null) {
233	            if (other.id != null)
234	                return false;
235	        } else if (!id.equals(other.id))
236	            return false;
237	        if (value == null) {
238	            if (other.value != null)
239	                return false;
240	        } else if (!value.equals(other.value))
241	            return false;
242	        if (priority == null) {
243	            if (other.priority != null)
244	                return false;
245	        } else if (!priority.equals(other.priority))
246	            return false;
247	        return true;
248	    }
