152	    private void merge(GroupRepresentation g1, GroupRepresentation g2) {
153	        if(g1.equals(g2)) {
154	            Map<String, GroupRepresentation> g1Children = g1.getSubGroups().stream().collect(Collectors.toMap(GroupRepresentation::getId, g -> g));
155	            Map<String, GroupRepresentation> g2Children = g2.getSubGroups().stream().collect(Collectors.toMap(GroupRepresentation::getId, g -> g));
156	
157	            g2Children.forEach((key, value) -> {
158	                if (g1Children.containsKey(key)) {
159	                    merge(g1Children.get(key), value);
160	                } else {
161	                    g1Children.put(key, value);
162	                }
163	            });
164	            g1.setSubGroups(new ArrayList<>(g1Children.values()));
165	        }
166	    }
