168	    @Override
169	    public boolean equals(Object o) {
170	        if (this == o) {
171	            return true;
172	        }
173	        if (o == null || getClass() != o.getClass()) {
174	            return false;
175	        }
176	        GroupRepresentation that = (GroupRepresentation) o;
177	        boolean isEqual = Objects.equals(id, that.id) && Objects.equals(parentId, that.parentId);
178	        if(isEqual) {
179	            return true;
180	        } else {
181	            return Objects.equals(name, that.name) && Objects.equals(path, that.path);
182	        }
183	    }
184	
185	    @Override
186	    public int hashCode() {
187	        if(id == null) {
188	            return Objects.hash(name, path);
189	        }
190	        return Objects.hash(id, parentId);
191	    }
