18	package org.keycloak.jose.jwe;
19	
20	import java.io.IOException;
21	
22	import org.keycloak.common.util.Base64Url;
23	import org.keycloak.jose.JOSE;
24	import org.keycloak.jose.JOSEHeader;
25	import org.keycloak.jose.jwe.JWEHeader.JWEHeaderBuilder;
26	import org.keycloak.jose.jwe.alg.JWEAlgorithmProvider;
27	import org.keycloak.jose.jwe.enc.JWEEncryptionProvider;
28	import org.keycloak.json.KeycloakJsonMapperFactory;
29	
30	/**
31	 * @author <a href="mailto:mposolda@redhat.com">Marek Posolda</a>
32	 */
33	public class JWE implements JOSE {
34	
35	    private JWEHeader header;
36	    private String base64Header;
37	
38	    private JWEKeyStorage keyStorage = new JWEKeyStorage();
39	    private String base64Cek;
40	
41	    private byte[] initializationVector;
42	
43	    private byte[] content;
44	    private byte[] encryptedContent;
45	
46	    private byte[] authenticationTag;
47	
48	    public JWE() {
49	    }
50	
51	    public JWE(String jwt) {
52	        setupJWEHeader(jwt);
53	    }
54	
55	    public JWE header(JWEHeader header) {
56	        this.header = header;
57	        this.base64Header = null;
58	        return this;
59	    }
60	
61	    public JOSEHeader getHeader() {
62	        if (header == null && base64Header != null) {
63	            try {
64	                byte[] decodedHeader = Base64Url.decode(base64Header);
65	                header = KeycloakJsonMapperFactory.mapper().readValue(decodedHeader, JWEHeader.class);
66	            } catch (IOException ioe) {
67	                throw new RuntimeException(ioe);
68	            }
69	        }
70	        return header;
71	    }
72	
73	    public String getBase64Header() throws IOException {
74	        if (base64Header == null && header != null) {
75	            byte[] contentBytes = KeycloakJsonMapperFactory.mapper().writeValueAsBytes(header);
76	            base64Header = Base64Url.encode(contentBytes);
77	        }
78	        return base64Header;
79	    }
80	
81	
82	    public JWEKeyStorage getKeyStorage() {
83	        return keyStorage;
84	    }
85	
86	
87	    public byte[] getInitializationVector() {
88	        return initializationVector;
89	    }
90	
91	
92	    public JWE content(byte[] content) {
93	        this.content = content;
94	        return this;
95	    }
96	
97	    public byte[] getContent() {
98	        return content;
99	    }
100	
101	    public byte[] getEncryptedContent() {
102	        return encryptedContent;
103	    }
104	
105	
106	    public byte[] getAuthenticationTag() {
107	        return authenticationTag;
108	    }
109	
110	
111	    public void setEncryptedContentInfo(byte[] initializationVector, byte[] encryptedContent, byte[] authenticationTag) {
112	        this.initializationVector = initializationVector;
113	        this.encryptedContent = encryptedContent;
114	        this.authenticationTag = authenticationTag;
115	    }
116	
117	
118	    public String encodeJwe() throws JWEException {
119	        try {
120	            if (header == null) throw new IllegalStateException("Header must be set");
121	            return encodeJwe(JWERegistry.getAlgProvider(header.getAlgorithm()), JWERegistry.getEncProvider(header.getEncryptionAlgorithm()));
122	        } catch (Exception e) {
123	            throw new JWEException(e);
124	        }
125	    }
126	
127	    public String encodeJwe(JWEAlgorithmProvider algorithmProvider, JWEEncryptionProvider encryptionProvider) throws JWEException {
128	        try {
129	            if (header == null) {
130	                throw new IllegalStateException("Header must be set");
131	            }
132	            if (content == null) {
133	                throw new IllegalStateException("Content must be set");
134	            }
135	
136	            if (algorithmProvider == null) {
137	                throw new IllegalArgumentException("No provider for alg '" + header.getAlgorithm() + "'");
138	            }
139	
140	            if (encryptionProvider == null) {
141	                throw new IllegalArgumentException("No provider for enc '" + header.getEncryptionAlgorithm() + "'");
142	            }
143	
144	            keyStorage.setEncryptionProvider(encryptionProvider);
145	            keyStorage.getCEKKey(JWEKeyStorage.KeyUse.ENCRYPTION, true); // Will generate CEK if it's not already present
146	
147	            JWEHeaderBuilder headerBuilder = header.toBuilder();
148	            byte[] encodedCEK = algorithmProvider.encodeCek(encryptionProvider, keyStorage, keyStorage.getEncryptionKey(), headerBuilder);
149	            base64Cek = Base64Url.encode(encodedCEK);
150	            header = headerBuilder.build();
151	
152	            encryptionProvider.encodeJwe(this);
153	
154	            return getEncodedJweString();
155	        } catch (Exception e) {
156	            throw new JWEException(e);
157	        }
158	    }
159	
160	    private String getEncodedJweString() {
161	        StringBuilder builder = new StringBuilder();
162	        builder.append(base64Header).append(".")
163	                .append(base64Cek).append(".")
164	                .append(Base64Url.encode(initializationVector)).append(".")
165	                .append(Base64Url.encode(encryptedContent)).append(".")
166	                .append(Base64Url.encode(authenticationTag));
167	
168	        return builder.toString();
169	    }
170	
171	    private void setupJWEHeader(String jweStr) throws IllegalStateException {
172	        String[] parts = jweStr.split("\\.");
173	        if (parts.length != 5) {
174	            throw new IllegalStateException("Not a JWE String");
175	        }
176	
177	        this.base64Header = parts[0];
178	        this.base64Cek = parts[1];
179	        this.initializationVector = Base64Url.decode(parts[2]);
180	        this.encryptedContent = Base64Url.decode(parts[3]);
181	        this.authenticationTag = Base64Url.decode(parts[4]);
182	
183	        this.header = (JWEHeader) getHeader();
184	    }
185	
186	    private JWE getProcessedJWE(JWEAlgorithmProvider algorithmProvider, JWEEncryptionProvider encryptionProvider) throws Exception {
187	        if (algorithmProvider == null) {
188	            throw new IllegalArgumentException("No provider for alg ");
189	        }
190	
191	        if (encryptionProvider == null) {
192	            throw new IllegalArgumentException("No provider for enc ");
193	        }
194	
195	        keyStorage.setEncryptionProvider(encryptionProvider);
196	
197	        byte[] decodedCek = algorithmProvider.decodeCek(Base64Url.decode(base64Cek), keyStorage.getDecryptionKey(), this.header, encryptionProvider);
198	        keyStorage.setCEKBytes(decodedCek);
199	
200	        encryptionProvider.verifyAndDecodeJwe(this);
201	
202	        return this;
203	    }
204	
205	    public JWE verifyAndDecodeJwe(String jweStr) throws JWEException {
206	        try {
207	            setupJWEHeader(jweStr);
208	            return verifyAndDecodeJwe();
209	        } catch (Exception e) {
210	            throw new JWEException(e);
211	        }
212	    }
213	
214	    public JWE verifyAndDecodeJwe(String jweStr, JWEAlgorithmProvider algorithmProvider, JWEEncryptionProvider encryptionProvider) throws JWEException {
215	        try {
216	            setupJWEHeader(jweStr);
217	            return getProcessedJWE(algorithmProvider, encryptionProvider);
218	        } catch (Exception e) {
219	            throw new JWEException(e);
220	        }
221	    }
222	
223	    public JWE verifyAndDecodeJwe() throws JWEException {
224	        try {
225	            return getProcessedJWE(JWERegistry.getAlgProvider(header.getAlgorithm()), JWERegistry.getEncProvider(header.getEncryptionAlgorithm()));
226	        } catch (Exception e) {
227	            throw new JWEException(e);
228	        }
229	    }
230	
231	}
