19	
20	
21	import java.net.URLDecoder;
22	import java.net.URLEncoder;
23	import java.nio.charset.StandardCharsets;
24	import java.util.Base64;
25	
26	/**
27	 * The default implementation is compliant with <a href="https://datatracker.ietf.org/doc/html/rfc2617">RFC 2617</a>
28	 *
29	 * @author <a href="mailto:bill@burkecentral.com">Bill Burke</a>
30	 * @version $Revision: 1 $
31	 */
32	public class BasicAuthHelper {
33	    public static String createHeader(String username, String password) {
34	        return "Basic " + Base64.getEncoder().encodeToString(
35	                ((username != null ? username : "") + ':' + (password != null ? password : ""))
36	                        .getBytes(StandardCharsets.UTF_8));
37	    }
38	
39	    public static String[] parseHeader(String header) {
40	        if (header.length() < 6) return null;
41	
42	        String type = header.substring(0, 5);
43	        type = type.toLowerCase();
44	        if (!type.equalsIgnoreCase("Basic")) return null;
45	
46	        String val;
47	        try {
48	            val = new String(Base64.getMimeDecoder().decode(header.substring(6)));
49	        } catch (IllegalArgumentException e) {
50	            return null;
51	        }
52	
53	        int separatorIndex = val.indexOf(":");
54	        if (separatorIndex == -1) return null;
55	
56	        String username = val.substring(0, separatorIndex);
57	        String password = val.substring(separatorIndex + 1);
58	
59	        return new String[]{ username, password };
60	    }
61	
62	    /**
63	     * compliant with <a href="https://datatracker.ietf.org/doc/html/rfc6749#section-2.3.1">RFC 6749</a>
64	     */
65	    public static abstract class RFC6749 {
66	
67	        public static String createHeader(String username, String password) {
68	            return BasicAuthHelper.createHeader(
69	                username != null ? URLEncoder.encode(username, StandardCharsets.UTF_8) : "",
70	                password != null ? URLEncoder.encode(password, StandardCharsets.UTF_8) : ""
71	            );
72	        }
73	
74	        public static String[] parseHeader(String header) {
75	            String[] val = BasicAuthHelper.parseHeader(header);
76	            if (null == val) {
77	                return null;
78	            }
79	
80	            return new String[]{
81	                URLDecoder.decode(val[0], StandardCharsets.UTF_8),
82	                URLDecoder.decode(val[1], StandardCharsets.UTF_8)
83	            };
84	        }
85	    }
86	}
