376	    public static Profile configure(ProfileConfigResolver... resolvers) {
377	        ProfileName profile = Arrays.stream(resolvers).map(ProfileConfigResolver::getProfileName).filter(Objects::nonNull).findFirst().orElse(ProfileName.DEFAULT);
378	
379	        Map<Feature, Boolean> features = new LinkedHashMap<>();
380	
381	        Map<Feature, Enablement> enablements = new LinkedHashMap<Profile.Feature, Enablement>();
382	
383	        for (Map.Entry<String, TreeSet<Feature>> entry : getOrderedFeatures().entrySet()) {
384	
385	            // first check by unversioned key - if enabled, choose the highest priority feature
386	            String unversionedFeature = entry.getKey();
387	            ProfileConfigResolver.FeatureConfig unversionedConfig = getFeatureConfig(unversionedFeature, resolvers);
388	            Feature enabledFeature = null;
389	            if (unversionedConfig == FeatureConfig.ENABLED) {
390	                enabledFeature = entry.getValue().iterator().next();
391	                if (!enabledFeature.isAvailable()) {
392	                    throw new ProfileException(String.format("Feature %s cannot be enabled as it is not available.", unversionedFeature));
393	                }
394	            } else if (unversionedConfig == FeatureConfig.DISABLED && ESSENTIAL_FEATURES.contains(unversionedFeature)) {
395	                throw new ProfileException(String.format("Feature %s cannot be disabled.", unversionedFeature));
396	            }
397	
398	            // now check each feature version to ensure consistency and select any features enabled by default
399	            boolean isExplicitlyEnabledFeature = false;
400	            for (Feature f : entry.getValue()) {
401	                ProfileConfigResolver.FeatureConfig configuration = getFeatureConfig(f.getVersionedKey(), resolvers);
402	
403	                if (configuration != FeatureConfig.UNCONFIGURED && unversionedConfig != FeatureConfig.UNCONFIGURED) {
404	                    throw new ProfileException("Versioned feature " + f.getVersionedKey() + " is not expected as " + unversionedFeature + " is already " + unversionedConfig.name().toLowerCase());
405	                }
406	
407	                switch (configuration) {
408	                case ENABLED:
409	                    if (isExplicitlyEnabledFeature) {
410	                        throw new ProfileException(
411	                                String.format("Multiple versions of the same feature %s, %s should not be enabled.",
412	                                        enabledFeature.getVersionedKey(), f.getVersionedKey()));
413	                    }
414	                    // even if something else was enabled by default, explicitly enabling a lower priority feature takes precedence
415	                    if (!f.isAvailable()) {
416	                        throw new ProfileException(String.format("Feature %s cannot be enabled as it is not available.", f.getVersionedKey()));
417	                    }
418	                    enabledFeature = f;
419	                    isExplicitlyEnabledFeature = true;
420	                    break;
421	                case DISABLED:
422	                    throw new ProfileException("Feature " + f.getVersionedKey() + " should not be disabled using a versioned key.");
423	                default:
424	                    if (unversionedConfig == FeatureConfig.UNCONFIGURED && enabledFeature == null
425	                            && isEnabledByDefault(profile, f) && f.isAvailable()) {
426	                        enabledFeature = f;
427	                    }
428	                    break;
429	                }
430	            }
431	            if (enabledFeature != null) {
432	                enablements.put(enabledFeature, isExplicitlyEnabledFeature ? Enablement.VERSIONED
433	                        : unversionedConfig == FeatureConfig.ENABLED ? Enablement.UNVERSIONED : Enablement.DEFAULT);
434	            }
435	            for (Feature f : entry.getValue()) {
436	                features.put(f, f == enabledFeature);
437	            }
438	        }
439	
440	        verifyConfig(features);
441	
442	        return init(profile, features, enablements);
443	    }
