465	    /**
466	     * Compute a map of unversioned feature keys to ordered sets (highest first) of features.  The priority order for features is:
467	     * <p>
468	     * <ul>
469	     * <li>The highest default supported version
470	     * <li>The highest non-default supported version
471	     * <li>The highest deprecated version
472	     * <li>The highest preview version
473	     * <li>The highest experimental version
474	     * <ul>
475	     * <p>
476	     * Note the {@link Type} enum is ordered based upon priority.
477	     */
478	    private static Map<String, TreeSet<Feature>> getOrderedFeatures() {
479	        if (FEATURES == null) {
480	            // "natural" ordering low to high between two features (type has precedence and then reversed version is used)
481	            Comparator<Feature> comparator = Comparator.comparing(Feature::getType).thenComparing(Comparator.comparingInt(Feature::getVersion).reversed());
482	            // aggregate the features by unversioned key
483	            HashMap<String, TreeSet<Feature>> features = new HashMap<>();
484	            Stream.of(Feature.values()).forEach(f -> features.compute(f.getUnversionedKey(), (k, v) -> {
485	                if (v == null) {
486	                    v = new TreeSet<>(comparator);
487	                }
488	                v.add(f);
489	                return v;
490	            }));
491	            FEATURES = features;
492	        }
493	        return FEATURES;
494	    }
